package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen1Test {











    @Test
    public void testEncodeBase64_ChunkedExceedsMaxSize() {
        byte[] input = new byte[100];
        // Chunked encoding adds separators and size headers, making it larger than standard.
        // We test that the size check works for chunked too.
        try {
            Base64.encodeBase64(input, true, false, 10);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Input array too big"));
        }
    }


}

